1	// Offline smoke tests: spec building, JWT signing, client request shape,
2	// polling, and HTTP routing. No network, no Nebius account needed.
3	import { test } from 'node:test';
4	import assert from 'node:assert/strict';
5	import { generateKeyPairSync, createVerify } from 'node:crypto';
6	import { buildJobRequest, buildTrainingJobRequest, estimateCost, parseDurationSeconds, SpecError, shellQuote } from './nebius/spec.js';
7	import { makeServiceAccountJwt, exchangeJwtForToken, createTokenProvider } from './nebius/auth.js';
8	import { NebiusJobsClient, summarizeJob, isTerminal } from './nebius/client.js';
9	import { createTrainingService, registerRoutes } from './routes/training-jobs.js';
10	import { Router } from '../../server.js';
11	
12	const ENV = { NEBIUS_PROJECT_ID: 'project-e00test', NEBIUS_SUBNET_ID: 'vpcsubnet-e00test' };
13	
14	test('parseDurationSeconds accepts h/m/s/d and numbers', () => {
15	  assert.equal(parseDurationSeconds('2h'), 7200);
16	  assert.equal(parseDurationSeconds('90m'), 5400);
17	  assert.equal(parseDurationSeconds('3600s'), 3600);
18	  assert.equal(parseDurationSeconds(3600), 3600);
19	  assert.equal(parseDurationSeconds('1d'), 86400);
20	  assert.throws(() => parseDurationSeconds('soon'), SpecError);
21	});
22	
23	test('buildJobRequest matches the Nebius quick-start shape', () => {
24	  const { request, estimate } = buildJobRequest({ name: 'my-job', image: 'nvidia/cuda:13.1.1-runtime-ubuntu24.04', command: 'bash', args: '-c nvidia-smi', platform: 'gpu-l40s-a', preset: '1gpu-8vcpu-32gb', timeout: '1h' }, ENV);
25	  assert.deepEqual(request.metadata, { parentId: 'project-e00test', name: 'my-job' });
26	  assert.equal(request.spec.image, 'nvidia/cuda:13.1.1-runtime-ubuntu24.04');
27	  assert.equal(request.spec.containerCommand, 'bash');
28	  assert.equal(request.spec.args, '-c nvidia-smi');
29	  assert.equal(request.spec.timeout, '3600s');
30	  assert.equal(request.spec.subnetId, 'vpcsubnet-e00test');
31	  assert.deepEqual(request.spec.disk, { type: 'NETWORK_SSD', sizeBytes: String(250 * 1024 ** 3) });
32	  assert.equal(estimate.maxCostUsd, 1.55);
33	});
34	
35	test('buildJobRequest validates name, preset, timeout, injected file size, volumes', () => {
36	  assert.throws(() => buildJobRequest({ name: 'Bad_Name' }, ENV), /lowercase/);
37	  assert.throws(() => buildJobRequest({ name: 'ok', platform: 'gpu-h100-sxm', preset: '1gpu-8vcpu-32gb' }, ENV), /not listed/);
38	  assert.throws(() => buildJobRequest({ name: 'ok', timeout: '10m' }, ENV), /between 1h and 168h/);
39	  assert.throws(() => buildJobRequest({ name: 'ok', injectedFiles: [{ containerPath: '/x', content: 'a'.repeat(64 * 1024 + 1) }] }, ENV), /64 KiB/);
40	  assert.throws(() => buildJobRequest({ name: 'ok', volumes: ['bucket:relative/path'] }, ENV), /absolute/);
41	  assert.throws(() => buildJobRequest({ name: 'ok' }, {}), /NEBIUS_PROJECT_ID/);
42	});
